const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const must = (c, msg) => { if (!c) throw new Error(`self-check failed: ${msg}`); };
const T = (p) => inr(p); // table cell, rupees without the symbol

// ---------------------------------------------------------------- worked examples, computed
// Deck 1
const we1 = sale(rs(6400), 12);
must(we1.gst === rs(768) && we1.cgst === rs(384) && we1.amount === rs(7168), 'D1 WE1');
const we2i = sale(rs(15500), 18, { inter: true }), we2a = sale(rs(15500), 18);
must(we2i.igst === rs(2790) && we2a.cgst === rs(1395) && we2i.amount === we2a.amount && we2i.amount === rs(18290), 'D1 WE2');
const we3Rows = [['School bag', rs(1200), 12], ['Scientific calculator', rs(850), 18], ['Pack of notebooks', rs(400), 5]];
const we3 = invoice(we3Rows.map(([, p, g]) => [p, g]));
must(we3.gst === rs(317) && we3.cgst === rs(158.5) && we3.amount === rs(2767), 'D1 WE3');
const we4 = bill(rs(24000), 15, 18);
must(we4.sp === rs(20400) && we4.gst === rs(3672) && we4.cgst === rs(1836) && we4.amount === rs(24072), 'D1 WE4');
const we5 = bill(rs(3600), 15, 12), we5i = bill(rs(3600), 15, 12, { inter: true });
must(we5.sp === rs(3060) && we5.gst === rs(367.2) && we5.cgst === rs(183.6) && we5i.igst === we5.gst && we5.amount === rs(3427.2), 'D1 WE5');
// Deck 2
const c1 = chain([rs(3000), rs(3600), rs(4200)], 18);
must(c1.stages.map((s) => s.pay).join() === [rs(540), rs(108), rs(108)].join() && c1.total === rs(756) && c1.stages.map((s) => s.cgstPay).join() === [rs(270), rs(54), rs(54)].join(), 'D2 WE1');
const noItc = c1.stages.reduce((s, x) => s + x.out.gst, 0);
must(noItc === rs(1944), 'cascade total');
const d2cost = rs(5000), d2mp = withProfit(d2cost, 20), d2sp = disc(d2mp, 10).sp, c2 = chain([d2cost, d2sp], 12), w2 = c2.stages[1];
must(d2mp === rs(6000) && d2sp === rs(5400) && w2.pay === rs(48) && w2.cgstPay === rs(24) && w2.out.amount === rs(6048) && profitPct(d2cost, d2sp) === 8, 'D2 WE2');
const c3 = chain([rs(40000), rs(46000)], 12, [false, true]), [c3m, c3d] = c3.stages;
must(c3m.out.cgst === rs(2400) && c3d.out.igst === rs(5520) && c3d.igstPay === rs(720), 'D2 WE3');
const we24 = baseFrom(rs(11092), 18), we24s = sale(we24, 18);
must(we24 === rs(9400) && we24s.cgst === rs(846), 'D2 WE4');
const we25sp = disc(rs(2500), 8).sp, we25g = rateFrom(we25sp, rs(2576));
must(we25sp === rs(2300) && we25g === 12, 'D2 WE5');
const we26sp = baseFrom(rs(4956), 18), we26l = listFrom(we26sp, 16);
must(we26sp === rs(4200) && we26l === rs(5000), 'D2 WE6');

// ---------------------------------------------------------------- visuals
const billFlow = flow('LR', [['p', 'Price of the article (after any discount)'], ['t', 'Add GST at the given rate'], ['a', 'Amount on the bill'], ['g', 'The seller passes the GST to the government']], [['p', 't'], ['t', 'a'], ['a', 'g']], 'Flow of a sale under GST: the price of the article after any discount, then GST at the given rate is added, giving the amount on the bill; the seller passes the GST on to the government.', 'GST is added to the price; the buyer pays it and the seller hands it over.');
const chainFlow = flow('LR', [['m', 'Manufacturer'], ['w', 'Wholesaler'], ['r', 'Retailer'], ['c', 'Consumer']], [['m', 'w', 'sale + GST'], ['w', 'r', 'sale + GST'], ['r', 'c', 'sale + GST']], 'Flow of a supply chain: manufacturer to wholesaler to retailer to consumer, with GST charged on each sale.', 'GST is charged at every sale in the chain, not only at the shop counter.');
const rateTable = table(['GST rate', 'CGST', 'SGST', 'IGST (inter-state)'], [5, 12, 18, 28].map((g) => [`${g}%`, `${g / 2}%`, `${g / 2}%`, `${g}%`]), 'Table of GST rates used in this chapter: 5 percent splits into 2.5 percent CGST and 2.5 percent SGST; 12 percent into 6 and 6; 18 percent into 9 and 9; 28 percent into 14 and 14. For an inter-state sale the whole rate is IGST.', 'Within a state the rate is halved; across states it is charged whole as IGST.');
for (const g of [5, 12, 18, 28]) must(sale(rs(1000), g).cgst === pctOf(rs(1000), g / 2), `rate table ${g}`);
const headsTable = table(['Sale', 'Example', 'Tax on the bill', 'Collected by'], [['Intra-state (same state)', 'Nagpur to Pune, both in Maharashtra', 'CGST + SGST, half the rate each', 'Centre (CGST) and the state (SGST)'], ['Inter-state (different states)', 'Coimbatore (Tamil Nadu) to Palakkad (Kerala)', 'IGST at the full rate', 'Centre, which shares it with the state where the goods are used']], 'Table comparing intra-state and inter-state sales: within one state, such as Nagpur to Pune, the bill shows CGST and SGST at half the rate each; between states, such as Coimbatore to Palakkad, it shows IGST at the full rate, collected by the Centre and shared with the destination state.', 'Where the buyer is decides the heads of tax, not the rate.');
const we1Table = table(['Item', 'Price (₹)', 'CGST 6% (₹)', 'SGST 6% (₹)', 'Amount (₹)'], [['Study table', T(we1.price), T(we1.cgst), T(we1.sgst), T(we1.amount)]], `Tax invoice line for a study table sold in Nagpur: price 6,400 rupees, CGST at 6 percent 384 rupees, SGST at 6 percent 384 rupees, amount 7,168 rupees.`, r`GST $= 12\% \text{ of } 6400 = 768$, split equally.`);
const we2Table = table(['If the buyer is in', 'Tax on the bill (₹)', 'Amount (₹)'], [['Palakkad, Kerala (inter-state)', `IGST ${T(we2i.igst)}`, T(we2i.amount)], ['Tiruppur, Tamil Nadu (intra-state)', `CGST ${T(we2a.cgst)} + SGST ${T(we2a.sgst)}`, T(we2a.amount)]], 'Table for a pump priced 15,500 rupees at 18 percent GST: sold to Palakkad in Kerala the bill shows IGST of 2,790 rupees; sold within Tamil Nadu it shows CGST 1,395 and SGST 1,395 rupees. The amount is 18,290 rupees either way.', 'Same rate and same total; only the heads of tax change.');
const invoiceParts = table(['On a tax invoice', 'What it tells you'], [['GSTIN of the seller (and of a registered buyer)', 'the 15-character GST identification number'], ['Description and HSN code of each item', 'what is sold; the code fixes its GST rate'], ['Taxable value', 'price after any discount, before tax'], ['CGST and SGST, or IGST', 'rate and amount of each tax'], ['Invoice value', 'taxable value + all the taxes']], 'Table listing the parts of a tax invoice: the GST identification numbers of the seller and a registered buyer, the description and HSN code of each item, the taxable value, the rate and amount of CGST and SGST or IGST, and the invoice value.', 'Every GST sum in this chapter is a line of such an invoice.');
const we3Table = table(['Item', 'Price (₹)', 'Rate', 'GST (₹)', 'CGST (₹)', 'SGST (₹)'], [...we3Rows.map(([n, , g], i) => [n, T(we3.rows[i].price), `${g}%`, T(we3.rows[i].gst), T(we3.rows[i].cgst), T(we3.rows[i].sgst)]), ['Total', T(we3.price), '', T(we3.gst), T(we3.cgst), T(we3.sgst)]], 'Invoice table of a Bhubaneswar stationery shop: school bag 1,200 rupees at 12 percent, GST 144; scientific calculator 850 rupees at 18 percent, GST 153; pack of notebooks 400 rupees at 5 percent, GST 20. Totals: price 2,450, GST 317, CGST 158.50, SGST 158.50.', `Invoice value $= 2450 + 317 = 2767$ rupees.`);
const discFlow = flow('LR', [['l', 'List (marked) price'], ['d', 'Minus discount'], ['s', 'Selling price (taxable value)'], ['t', 'Plus GST on the selling price'], ['a', 'Amount paid']], [['l', 'd'], ['d', 's'], ['s', 't'], ['t', 'a']], 'Flow for a discounted sale: list price, minus the discount, gives the selling price, which is the taxable value; GST is added on the selling price to give the amount paid.', 'Discount first, then tax on what is left.');
const we4Bars = plot({ x: [0, 5], y: [0, 26], xl: 'step', yl: 'thousands of rupees', series: [{ label: 'List price', points: [[1, rup(we4.list) / 1000]], kind: 'bar' }, { label: 'After 15% discount', points: [[2, rup(we4.sp) / 1000]], kind: 'bar' }, { label: 'GST at 18%', points: [[3, rup(we4.gst) / 1000]], kind: 'bar' }, { label: 'Amount paid', points: [[4, rup(we4.amount) / 1000]], kind: 'bar' }] }, 'Bar chart for a refrigerator: list price 24 thousand rupees, price after a 15 percent discount 20.4 thousand, GST at 18 percent 3.672 thousand, and amount paid 24.072 thousand rupees.', 'The amount paid ends up just above the list price.');
must(we4.list === rs(24000) && rup(we4.amount) / 1000 === 24.072, 'bars');
const mistakePlot = plot({ x: [0, 30], y: [0, 36], xl: 'list price (thousand rupees)', yl: 'amount paid (thousand rupees)', fns: [{ expr: '1.18*x', label: 'GST on the list price (wrong)' }, { expr: '1.003*x', label: '15% off, then 18% GST (right)' }], pts: [[24, 28.32, '(24, 28.32)'], [24, 24.072, '(24, 24.072)']] }, 'Graph of amount paid against list price. The steep line, 1.18 times the list price, is the wrong method of taxing the list price; the lower line, 1.003 times the list price, is the right method of taking 15 percent off and then adding 18 percent GST. At a list price of 24 thousand rupees the lines give 28.32 and 24.072 thousand rupees.', 'Taxing the list price would overcharge by more than four thousand rupees here.');
must(Math.abs(0.85 * 1.18 - 1.003) < 1e-12 && rup(pctOf(rs(24000), 118)) === 28320, 'multipliers');
const we5Table = table(['Seller and buyer', 'Selling price (₹)', 'Tax (₹)', 'Amount (₹)'], [['Both in Srinagar', T(we5.sp), `CGST ${T(we5.cgst)} + SGST ${T(we5.sgst)}`, T(we5.amount)], ['Seller in Ludhiana, buyer in Srinagar', T(we5i.sp), `IGST ${T(we5i.igst)}`, T(we5i.amount)]], 'Table for a woollen jacket listed at 3,600 rupees with 15 percent off: selling price 3,060 rupees; within Srinagar CGST 183.60 and SGST 183.60 rupees; from Ludhiana in Punjab to Srinagar IGST 367.20 rupees. The amount is 3,427.20 rupees in both cases.', 'Discount and tax are the same; the heads of tax depend on the states.');
const summary1 = table(['Idea', 'Rule'], [['GST on a price', r`$\text{GST} = \dfrac{\text{rate}}{100} \times \text{price}$`], ['Intra-state', r`$\text{CGST} = \text{SGST} = \dfrac{1}{2}\,\text{GST}$`], ['Inter-state', r`$\text{IGST} = \text{GST}$ at the full rate`], ['Bill', r`$\text{amount} = \text{price} + \text{GST}$`], ['With a discount', 'GST on the price after discount']], 'Summary table of part one: GST is the rate over 100 times the price; within a state CGST and SGST are each half the GST; between states IGST is the whole GST; the amount is price plus GST; with a discount, GST is charged on the reduced price.', 'Part 1 on one card.');
