const cascade = table(['Stage', 'Selling price (₹)', 'Tax if each sale were taxed in full (₹)', 'Tax actually paid with input tax credit (₹)'], [...['Manufacturer', 'Wholesaler', 'Retailer'].map((n, i) => [n, T(c1.stages[i].price), T(c1.stages[i].out.gst), T(c1.stages[i].pay)]), ['Total', '', T(noItc), T(c1.total)]], 'Table comparing a chain with and without input tax credit at 18 percent: without credit the manufacturer, wholesaler and retailer would pay 540, 648 and 756 rupees, total 1,944; with credit they pay 540, 108 and 108, total 756.', 'Without input tax credit, tax would be charged on tax (a cascade).');
const c1Table = table(['Stage', 'Sells for (₹)', 'Output tax (₹)', 'Input tax (₹)', 'Net GST (₹)', 'CGST (₹)', 'SGST (₹)'], c1.stages.map((s, i) => [['Manufacturer (Surat)', 'Wholesaler (Vadodara)', 'Retailer (Rajkot)'][i], T(s.price), T(s.out.gst), T(s.input.gst), T(s.pay), T(s.cgstPay), T(s.sgstPay)]), 'Table of the Gujarat chain at 18 percent: manufacturer sells for 3,000, output tax 540, no input tax, pays 540 as 270 CGST and 270 SGST; wholesaler sells for 3,600, output 648, input 540, pays 108 as 54 and 54; retailer sells for 4,200, output 756, input 648, pays 108 as 54 and 54.', 'Each row: output tax minus input tax, then halve.');
