const we2Flow = flow('LR', [['c', `Cost ${R(d2cost)}`], ['m', `Marked price ${R(d2mp)}`], ['s', `Selling price ${R(d2sp)}`], ['a', `Customer pays ${R(w2.out.amount)}`]], [['c', 'm', '+20%'], ['m', 's', '−10%'], ['s', 'a', '+12% GST']], 'Flow for a harmonium: cost 5,000 rupees, marked 20 percent higher at 6,000, sold after a 10 percent discount at 5,400, and the customer pays 6,048 rupees after 12 percent GST.', `Net GST $= 648 - 600 = 48$ rupees.`);
const interTable = table(['Link', 'Tax charged', 'Input tax set off', 'Paid to the government'], [['Ludhiana maker to Ludhiana distributor (intra-state)', `CGST ${T(c3m.out.cgst)} + SGST ${T(c3m.out.sgst)}`, 'none', T(c3m.pay)], ['Ludhiana distributor to Jaipur retailer (inter-state)', `IGST ${T(c3d.out.igst)}`, `CGST + SGST ${T(c3d.input.gst)}`, `IGST ${T(c3d.igstPay)}`]], 'Table for woollen blankets at 12 percent: the Ludhiana maker sells to a Ludhiana distributor for 40,000 rupees with CGST 2,400 and SGST 2,400; the distributor sells to a Jaipur retailer for 46,000 rupees with IGST 5,520, sets off the 4,800 rupees of input tax and pays 720 rupees of IGST.', 'Input CGST and SGST can both be used against output IGST.');
const reverseTable = table(['Find', 'Rule'], [['Price before GST', r`$\text{price} = \text{amount} \times \dfrac{100}{100 + r}$`], ['Rate of GST', r`$r = \dfrac{\text{amount} - \text{price}}{\text{price}} \times 100$`], ['Price after discount', r`$\text{amount} \div \left(1 + \dfrac{r}{100}\right)$`], ['List price', r`$\text{selling price} \div \left(1 - \dfrac{d}{100}\right)$`], ['Rate of discount', r`$d = \dfrac{\text{list} - \text{selling price}}{\text{list}} \times 100$`]], 'Table of rules for reverse problems: price before GST is amount times 100 over 100 plus r; rate of GST is the tax over the price times 100; price after discount is the amount divided by 1 plus r over 100; list price is the selling price divided by 1 minus d over 100; rate of discount is the discount over the list price times 100.', 'Work backwards: undo the tax first, then the discount.');
